// The '...' here is the REST parameter collecting the arguments
function calculateOrder(discount, ...prices) {
  const total = prices.reduce((acc, curr) => acc + curr, 0);
  return total - discount;
}

// 5 is discount, the rest (10, 20, 30) become the 'prices' array
console.log(calculateOrder(5, 10, 20, 30)); // 55
